<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use ReadyFinance\{Core,Finance,Accounting,PlanManagementService,TransactionEditingService,AccountManagementService,Fault};
$c=new Core();if(!str_starts_with((string)$c->query('SELECT DATABASE()')->fetchColumn(),'readyfinance_entrytest_'))throw new RuntimeException('Synthetic installation required.');
$h=(int)$c->query('SELECT MIN(id) FROM households')->fetchColumn();$u=(int)$c->query('SELECT MIN(id) FROM users')->fetchColumn();$key='plan-test:'.bin2hex(random_bytes(5));$count=0;$f=new Finance($c);$a=new Accounting($c);$service=new PlanManagementService($c);$today=$c->today($h);$month=substr($today,0,7);
function ok(bool $yes,string $label):void{global $count;if(!$yes)throw new RuntimeException('FAIL: '.$label);$count++;echo 'PASS: '.$label.PHP_EOL;}
function rejects(callable $fn,string $label,int $status=422):void{try{$fn();}catch(Fault $e){ok($e->status===$status,$label);return;}throw new RuntimeException('FAIL: '.$label);}
function eq($a,$b):bool{return bccomp((string)$a,(string)$b,6)===0;}
function change(string $kind,string $uuid,string $action,array $values=[],?string $requestKey=null):array{global $service,$h,$u,$key;$r=$service->details($h,$kind,$uuid)['record'];return $service->change($h,$u,$values+['kind'=>$kind,'uuid'=>$uuid,'action'=>$action,'row_version'=>$r['row_version'],'reason'=>'Synthetic plan verification'],$requestKey??$key.':'.Core::uuid());}
$service->upgrade();ok($service->ready(),'Owner upgrade enables plan management');$service->upgrade();ok($service->ready(),'Planning migration is repeatable');
$bank=$f->create($h,$u,'account',['name'=>'Plan bank '.$key,'type'=>'bank','opening'=>'1000','opening_date'=>$today],$key.':bank');
$cat=$f->create($h,$u,'category',['name'=>'Plan expense '.$key,'type'=>'expense'],$key.':cat')['uuid'];$other=$f->create($h,$u,'category',['name'=>'Plan other '.$key,'type'=>'expense'],$key.':other')['uuid'];
$budget=$f->create($h,$u,'budget',['category_uuid'=>$cat,'month'=>$month,'amount'=>'100'],$key.':budget')['uuid'];$stale=$service->details($h,'budget',$budget)['record'];
change('budget',$budget,'update',['category_uuid'=>$cat,'month'=>$month,'amount'=>'150']);ok(eq($service->details($h,'budget',$budget)['record']['amount'],'150'),'Budget amount can be edited');
rejects(fn()=>$service->change($h,$u,['kind'=>'budget','uuid'=>$budget,'action'=>'delete','row_version'=>$stale['row_version'],'reason'=>'Stale change'],$key.':stale'),'Concurrent budget edit is rejected',409);
change('budget',$budget,'delete');ok($service->details($h,'budget',$budget)['record']['archived']==1,'Budget deletion retains a restorable record');
change('budget',$budget,'restore');ok(!$service->details($h,'budget',$budget)['record']['archived'],'Budget restores its previous amount');
$reset=$f->create($h,$u,'budget',['category_uuid'=>$cat,'month'=>$month,'amount'=>'175'],$key.':reset');ok($reset['uuid']===$budget,'Setting an existing budget returns its actual UUID');
$bill=$f->create($h,$u,'bill',['name'=>'Plan bill '.$key,'amount'=>'80','due_date'=>$today,'category_uuid'=>$cat],$key.':bill')['uuid'];
$payment=$a->post($h,$u,['type'=>'expense','account_uuid'=>$bank['uuid'],'category_uuid'=>$cat,'bill_uuid'=>$bill,'amount'=>'20','date'=>$today,'description'=>'Synthetic partial bill'],$key.':billpay');
$journalCount=(int)$c->query('SELECT COUNT(*) FROM journal_entries WHERE household_id=?',[$h])->fetchColumn();
change('bill',$bill,'update',['name'=>'Updated plan bill '.$key,'amount'=>'90','due_date'=>$today,'category_uuid'=>$cat]);ok(eq($service->details($h,'bill',$bill)['record']['paid'],'20'),'Bill edit preserves partial payments');
rejects(fn()=>change('bill',$bill,'update',['name'=>'Bad','amount'=>'10','due_date'=>$today,'category_uuid'=>$cat]),'Bill total cannot fall below existing payments');
rejects(fn()=>change('bill',$bill,'update',['name'=>'Bad','amount'=>'90','due_date'=>$today,'category_uuid'=>$other]),'Paid bill category cannot silently change');
change('bill',$bill,'delete');ok(eq($c->balance($h,(int)$c->scope('accounts',$bank['uuid'],$h)['ledger_id']),'980'),'Deleting a paid bill leaves cash and expense postings intact');
rejects(fn()=>$a->post($h,$u,['type'=>'expense','account_uuid'=>$bank['uuid'],'category_uuid'=>$cat,'bill_uuid'=>$bill,'amount'=>'1','date'=>$today],$key.':deletedpay'),'Deleted bills reject new payments');change('bill',$bill,'restore');
$fund=$f->create($h,$u,'fund',['name'=>'Plan goal '.$key,'account_uuid'=>$bank['uuid'],'target'=>'500','purpose'=>'goal'],$key.':fund')['uuid'];$f->reserve($h,$u,['fund_uuid'=>$fund,'amount'=>'100'],$key.':reserve');
$staleFund=$service->details($h,'fund',$fund)['record'];$f->reserve($h,$u,['fund_uuid'=>$fund,'amount'=>'1'],$key.':reserveextra');
rejects(fn()=>$service->change($h,$u,['kind'=>'fund','uuid'=>$fund,'action'=>'delete','row_version'=>$staleFund['row_version'],'reason'=>'Stale reservation view'],$key.':stalefund'),'Reservation changes invalidate open goal deletion forms',409);$f->reserve($h,$u,['fund_uuid'=>$fund,'amount'=>'1','action'=>'release'],$key.':releaseextra');
change('fund',$fund,'update',['name'=>'Updated goal '.$key,'account_uuid'=>$bank['uuid'],'target'=>'600','purpose'=>'sinking_fund']);ok(eq($service->details($h,'fund',$fund)['record']['reserved'],'100'),'Goal edit keeps reservations');
$second=$f->create($h,$u,'account',['name'=>'Second plan bank '.$key,'type'=>'bank','opening'=>'0'],$key.':second')['uuid'];
rejects(fn()=>change('fund',$fund,'update',['name'=>'Bad','account_uuid'=>$second,'target'=>'600','purpose'=>'goal']),'A reserved goal cannot switch backing accounts');
$beforeDelete=$service->details($h,'fund',$fund)['record'];$payload=['kind'=>'fund','uuid'=>$fund,'action'=>'delete','row_version'=>$beforeDelete['row_version'],'reason'=>'Synthetic goal deletion'];$deleteKey=$key.':deletegoal';$first=$service->change($h,$u,$payload,$deleteKey);$again=$service->change($h,$u,$payload,$deleteKey);
ok($first===$again&&eq($service->details($h,'fund',$fund)['record']['reserved'],'0'),'Goal deletion releases reservations once on retry');
ok($f->reserve($h,$u,['fund_uuid'=>$fund,'amount'=>'100'],$key.':reserve')['saved']&&eq($service->details($h,'fund',$fund)['record']['reserved'],'0'),'Old reservation retries stay idempotent after goal deletion');
rejects(fn()=>$f->reserve($h,$u,['fund_uuid'=>$fund,'amount'=>'1'],$key.':deletedreserve'),'Deleted goals reject new reservations');change('fund',$fund,'restore');ok(eq($service->details($h,'fund',$fund)['record']['reserved'],'0'),'Restoring a goal does not silently re-reserve money');
ok($journalCount===(int)$c->query('SELECT COUNT(*) FROM journal_entries WHERE household_id=?',[$h])->fetchColumn(),'Plan metadata edits and goal deletion never create cash journals');
$debt=$f->create($h,$u,'debt',['name'=>'Plan borrower '.$key,'direction'=>'borrowed','amount'=>'100','account_uuid'=>$bank['uuid'],'date'=>$today],$key.':debt')['uuid'];
change('debt',$debt,'update',['name'=>'Renamed borrower '.$key,'due_date'=>$today]);$r=$service->details($h,'debt',$debt);ok($r['record']['name']===$c->scope('ledger_accounts',$r['record']['ledger_uuid'],$h)['name'],'Loan rename synchronizes its posting account');
rejects(fn()=>change('debt',$debt,'update',['name'=>'Bad','amount'=>'999']),'Loan principal cannot be overwritten as metadata');rejects(fn()=>change('debt',$debt,'delete'),'Outstanding loan deletion is rejected');
$tx=$r['transactions'][0];$editor=new TransactionEditingService($c);$details=$editor->details($h,$tx['uuid']);$p=$details['payload'];$p['amount']='120';$replacement=$editor->edit($h,$u,['uuid'=>$tx['uuid'],'row_version'=>$details['transaction']['row_version'],'reason'=>'Correct synthetic loan principal','payload'=>$p],$key.':loanedit');
ok(eq($service->details($h,'debt',$debt)['record']['remaining'],'120'),'Linked transaction edit corrects loan principal through balanced journals');
$repay=$a->post($h,$u,['type'=>'repay','account_uuid'=>$bank['uuid'],'obligation_uuid'=>$debt,'amount'=>'10','date'=>$today],$key.':repay');
rejects(fn()=>$a->reverse($h,$u,$replacement['uuid'],$today,'Mistaken loan',$key.':badreverse'),'Loan reversal protects dependent repayments',409);
$a->reverse($h,$u,$repay['uuid'],$today,'Mistaken repayment',$key.':repayreverse');$a->reverse($h,$u,$replacement['uuid'],$today,'Mistaken loan',$key.':loanreverse');change('debt',$debt,'delete');ok($service->details($h,'debt',$debt)['record']['archived']==1,'Zero-balance loan can be deleted while history remains');
rejects(fn()=>$a->post($h,$u,['type'=>'borrow','account_uuid'=>$bank['uuid'],'obligation_uuid'=>$debt,'amount'=>'1','date'=>$today],$key.':deletedloan'),'Deleted loans reject new movements');change('debt',$debt,'restore');ok(count($service->details($h,'debt',$debt)['transactions'])===0,'Restored reversed loan has no current financial entries');
$lent=$f->create($h,$u,'debt',['name'=>'Plan lent '.$key,'direction'=>'lent','amount'=>'50','account_uuid'=>$bank['uuid'],'date'=>$today],$key.':lent')['uuid'];change('debt',$lent,'update',['name'=>'Updated lent '.$key]);$a->post($h,$u,['type'=>'collect','account_uuid'=>$bank['uuid'],'obligation_uuid'=>$lent,'amount'=>'50','date'=>$today],$key.':collect');change('debt',$lent,'delete');ok($service->details($h,'debt',$lent)['record']['archived']==1,'Settled lending records support edit and deletion');
$rule=$f->create($h,$u,'recurring',['name'=>'Plan schedule '.$key,'amount'=>'9','category_uuid'=>$cat,'frequency'=>'monthly','next_date'=>$today],$key.':rule')['uuid'];
change('recurring',$rule,'update',['name'=>'Paused plan schedule '.$key,'amount'=>'12','category_uuid'=>$cat,'frequency'=>'monthly','next_date'=>$today,'active'=>'0']);$f->runRecurring($h,$u);$ruleRow=$c->scope('recurring_rules',$rule,$h);ok(!$c->one('SELECT bill_id FROM recurring_occurrences WHERE rule_id=?',[$ruleRow['id']]),'Paused schedules generate no bills');
change('recurring',$rule,'update',['name'=>'Running plan schedule '.$key,'amount'=>'12','category_uuid'=>$cat,'frequency'=>'monthly','next_date'=>$today,'active'=>'1']);change('recurring',$rule,'delete');$f->runRecurring($h,$u);ok(!$c->one('SELECT bill_id FROM recurring_occurrences WHERE rule_id=?',[$ruleRow['id']]),'Deleted schedules generate no bills');
change('recurring',$rule,'restore');$f->runRecurring($h,$u);$occ=$c->one('SELECT bill_id FROM recurring_occurrences WHERE rule_id=?',[$ruleRow['id']]);ok((bool)$occ,'Restored running schedules generate due bills');
change('recurring',$rule,'update',['name'=>'Future plan schedule '.$key,'amount'=>'15','category_uuid'=>$cat,'frequency'=>'weekly','next_date'=>(new DateTimeImmutable($today))->modify('+7 days')->format('Y-m-d'),'active'=>'1']);ok(eq($c->one('SELECT amount FROM bills WHERE id=?',[$occ['bill_id']])['amount'],'12'),'Schedule edits preserve already generated bill amounts');
rejects(fn()=>$service->details($h+999999,'budget',$budget),'Plans are scoped to the authorized household',404);rejects(fn()=>$service->details($h,'unsupported',$budget),'Unknown plan kinds are rejected');
$audit=$c->query('SELECT COUNT(*) FROM audit_events WHERE household_id=? AND entity_uuid=? AND action=?',[$h,$fund,'fund.delete'])->fetchColumn();ok((int)$audit===1,'Retry creates only one deletion audit event');
ok(!$c->one('SELECT journal_id FROM journal_lines WHERE household_id=? GROUP BY journal_id HAVING SUM(debit)<>SUM(credit)',[$h]),'All journals remain balanced after plan and loan changes');
$current=$service->details($h,'budget',$budget)['record'];$c->query('UPDATE periods SET locked=1 WHERE household_id=? AND month=?',[$h,$month]);
try{rejects(fn()=>change('budget',$budget,'delete'),'Locked-period budgets cannot be deleted',409);rejects(fn()=>change('budget',$budget,'update',['category_uuid'=>$cat,'month'=>$month,'amount'=>'1']),'Locked-period budgets cannot be edited',409);}finally{$c->query('UPDATE periods SET locked=0 WHERE household_id=? AND month=?',[$h,$month]);}
rejects(fn()=>change('budget',$budget,'update',['category_uuid'=>$cat,'month'=>$month,'amount'=>'0']),'Zero planned amounts are rejected');
$snapshot=$f->snapshot($h,$c->one('SELECT u.*,m.role FROM users u JOIN household_memberships m ON m.user_id=u.id WHERE u.id=? AND m.household_id=?',[$u,$h]));ok($snapshot['planning_ready']&&in_array($budget,array_column($snapshot['budgets'],'uuid')),'Snapshot includes editable plan identities');
$c->db->beginTransaction();try{$c->query("DELETE FROM schema_migrations WHERE version='007_planning'");$legacy=$f->snapshot($h,$c->one('SELECT u.*,m.role FROM users u JOIN household_memberships m ON m.user_id=u.id WHERE u.id=? AND m.household_id=?',[$u,$h]));ok(!$legacy['planning_ready'],'Snapshot remains usable before enabling the planning upgrade');}finally{$c->db->rollBack();}
$moveCat=$f->create($h,$u,'category',['name'=>'Plan move '.$key,'type'=>'expense'],$key.':movecat')['uuid'];$moveBudget=$f->create($h,$u,'budget',['category_uuid'=>$moveCat,'month'=>$month,'amount'=>'25'],$key.':movebudget')['uuid'];change('budget',$moveBudget,'delete');
$oldBudget=$service->details($h,'budget',$moveBudget)['record'];$editor->moveCategory($h,$u,['source_uuid'=>$cat,'target_uuid'=>$moveCat,'reason'=>'Move into a deleted budget slot','archive'=>false],$key.':moveplans');
$nowBudget=$service->details($h,'budget',$moveBudget)['record'];ok(!$nowBudget['archived']&&eq($nowBudget['amount'],$current['amount']),'Category moves reuse a deleted destination without adding its old amount');ok($nowBudget['row_version']>$oldBudget['row_version'],'Category moves invalidate stale plan editors');ok($service->details($h,'budget',$budget)['record']['archived']==1&&eq($service->details($h,'budget',$budget)['record']['amount'],$current['amount']),'Merged source budgets keep their old amount for restoration');
echo $count.' planning checks passed.'.PHP_EOL;
